# Standalone, stdlib-free, no imports, no I/O, no globals/nonlocals. Entry point verify(witness) raises AssertionError on any failed check.

def submasks(A):
    s = A
    while True:
        yield s
        if s == 0:
            return
        s = (s - 1) & A

def hered_subfams(G, m):
    if m == 0:
        return [frozenset(), frozenset(G)] if G else [frozenset()]
    e = 1 << (m - 1)
    G0 = frozenset(A for A in G if not (A & e))
    G1 = frozenset(A & ~e for A in G if A & e)
    out = []
    seen = set()
    for K0 in hered_subfams(G0, m - 1):
        for K1 in hered_subfams(G1 & K0, m - 1):
            K = frozenset(K0) | frozenset(A | e for A in K1)
            if K not in seen:
                seen.add(K)
                out.append(K)
    return out

def hered_families(m):
    if m == 0:
        return [frozenset(), frozenset([0])]
    e = 1 << (m - 1)
    out = []
    seen = set()
    for G in hered_families(m - 1):
        for K in hered_subfams(G, m - 1):
            F = frozenset(G) | frozenset(A | e for A in K)
            if F not in seen:
                seen.add(F)
                out.append(F)
    return out

def check_family(F):
    for A in F:
        for s in submasks(A):
            if s not in F:
                return False
    maximals = [A for A in F if not any((A & B) == A and B != A for B in F)]
    dc = set()
    for A in maximals:
        dc.update(submasks(A))
    return dc == set(F)

def pc(x):
    return bin(x).count('1')

def max_intersecting(members):
    n = len(members)
    adj = []
    for A in members:
        a = 0
        for j, B in enumerate(members):
            if B != A and (A & B) == 0:
                a |= 1 << j
        adj.append(a)
    def mis(cand):
        if cand == 0:
            return 0
        b = cand & (-cand)
        v = b.bit_length() - 1
        rest = cand ^ b
        skip = mis(rest)
        take = 1 + mis(rest & ~adj[v])
        return skip if skip > take else take
    return mis((1 << n) - 1)

def verify(witness):
    n_min = int(witness['n_min'])
    n_max = int(witness['n_max'])
    counts = witness['dedekind_counts']
    assert n_min == 1 and n_max == 5
    total = 0
    for m in range(n_min, n_max + 1):
        fams = hered_families(m)
        assert len(fams) == int(counts[str(m)]), 'count n=%d got=%d' % (m, len(fams))
        for F in fams:
            assert check_family(F), 'structure n=%d' % m
            ne = sorted(A for A in F if A)
            stars = [sum(1 for A in ne if (A >> x) & 1) for x in range(m)]
            mi = max_intersecting(ne)
            assert mi == max(stars), 'bound n=%d' % m
        total += len(fams)
    assert total == int(witness['total'])
    return True

verify({"n_min": 1, "n_max": 5, "dedekind_counts": {"1": 3, "2": 6, "3": 20, "4": 168, "5": 7581}, "total": 7778})
